<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';
import PasswordInput from './PasswordInput.vue';
const props=defineProps<{api:(path:string,method?:string,body?:unknown)=>Promise<any>}>();
const emit=defineEmits<{updated:[value:any];credentials:[];passwordChanged:[]}>();
const user=ref<any>(),credentials=ref<any>(),users=ref<any[]>([]),busy=ref(false),message=ref('');
const modelKey=ref(''),githubToken=ref(''),clearModel=ref(false),clearGithub=ref(false),name=ref(''),currentPassword=ref(''),newPassword=ref(''),repeatPassword=ref('');
async function refresh(){user.value=await props.api('account');credentials.value=await props.api('account/credentials');if(user.value.role==='owner')users.value=(await props.api('account/users')).items;}
onMounted(()=>refresh().catch(e=>message.value=e.message));onUnmounted(()=>{modelKey.value='';githubToken.value='';currentPassword.value='';newPassword.value='';repeatPassword.value='';});
async function run(action:()=>Promise<void>){busy.value=true;message.value='';try{await action();}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
async function saveCredentials(){await run(async()=>{const body:Record<string,string>={};if(clearModel.value||modelKey.value)body.modelKey=clearModel.value?'':modelKey.value;if(clearGithub.value||githubToken.value)body.githubToken=clearGithub.value?'':githubToken.value;if(!Object.keys(body).length){message.value='填写要更新的密钥，或选择清除。留空会保留原值。';return;}credentials.value=await props.api('account/credentials','PUT',body);modelKey.value='';githubToken.value='';clearModel.value=false;clearGithub.value=false;message.value='凭据已加密保存并生效。不会自动调用模型。';emit('credentials');});}
async function bind(){await run(async()=>{user.value=await props.api('account/bind','POST',{username:name.value,currentPassword:currentPassword.value});currentPassword.value='';emit('updated',user.value);message.value='用户名已绑定。下次请使用用户名和原密码登录。';await refresh();});}
async function password(){await run(async()=>{if(newPassword.value!==repeatPassword.value){message.value='两次输入的新密码不一致。';return;}await props.api('account/password','POST',{currentPassword:currentPassword.value,newPassword:newPassword.value});currentPassword.value='';newPassword.value='';repeatPassword.value='';emit('passwordChanged');});}
async function disable(account:any){await run(async()=>{await props.api('account/users/'+account.id,'PUT',{disabled:!account.disabled});await refresh();message.value=account.disabled?'账号已启用。':'账号已停用，会话已撤销，正在执行的工作已停止。';});}
</script>
<template>
  <section class="panel account-panel" aria-label="账号与凭据" v-if="user">
    <div class="section-heading"><h2>账号与个人凭据</h2><span class="badge">{{user.username||'待绑定管理员'}} · {{user.role==='owner'?'管理员':'个人账号'}}</span></div>
    <p class="muted">任务、技术画像、模型配置及用量仅属于当前账号。模型 API Key 和 GitHub Token 加密保存在服务端，页面不会回显原值。</p>
    <form v-if="user.needsBinding" class="account-section" @submit.prevent="bind"><h3>绑定管理员用户名</h3><p class="muted">保留现有任务和配置。绑定完成后，旧的免用户名入口将关闭。</p><label for="bind-name">用户名<input id="bind-name" v-model="name" required minlength="3" maxlength="32" pattern="[A-Za-z][A-Za-z0-9_-]{2,31}" autocomplete="username"></label><label for="bind-password">原管理员密码</label><PasswordInput id="bind-password" v-model="currentPassword" :autofocus="false" /><button :disabled="busy">绑定用户名</button></form>
    <form v-if="credentials" class="account-section" @submit.prevent="saveCredentials"><h3>我的 API 凭据</h3><p class="muted">模型密钥：{{credentials.modelKeyPresent?'已配置':'未配置'}} · GitHub 令牌：{{credentials.githubTokenPresent?'已配置':'未配置（可匿名读取公开仓库）'}}</p><div class="fields"><label>DeepSeek API Key<input v-model="modelKey" type="password" autocomplete="off" maxlength="512" :disabled="clearModel" placeholder="填写新密钥，留空保留原值"></label><label>GitHub Token<input v-model="githubToken" type="password" autocomplete="off" maxlength="512" :disabled="clearGithub" placeholder="填写新令牌，留空保留原值"></label></div><div class="account-checks"><label><input v-model="clearModel" type="checkbox">清除模型密钥</label><label><input v-model="clearGithub" type="checkbox">清除 GitHub 令牌</label></div><button :disabled="busy">保存个人凭据</button></form>
    <details v-if="!user.needsBinding" class="account-section"><summary>修改登录密码</summary><form @submit.prevent="password"><label for="current-password">当前密码</label><PasswordInput id="current-password" v-model="currentPassword" :autofocus="false" /><label for="new-password">新密码（至少 12 个字符）</label><PasswordInput id="new-password" v-model="newPassword" autocomplete="new-password" :min-length="12" :autofocus="false" /><label for="repeat-password">确认新密码</label><PasswordInput id="repeat-password" v-model="repeatPassword" autocomplete="new-password" :min-length="12" :autofocus="false" /><p class="muted">修改后所有设备会话立即退出，需要重新登录。</p><button :disabled="busy">修改密码并退出登录</button></form></details>
    <details v-if="user.role==='owner'" class="account-section"><summary>管理注册账号</summary><div v-for="account in users" :key="account.id" class="account-user"><span>{{account.username||'待绑定管理员'}} · {{account.disabled?'已停用':'正常'}}</span><button v-if="account.role!=='owner'" type="button" :disabled="busy" @click="disable(account)">{{account.disabled?'启用':'停用'}}</button></div></details>
    <p v-if="message" role="status" class="notice">{{message}}</p>
  </section>
</template>
<style scoped>
.account-panel{margin-bottom:28px}.account-panel h3{font-size:16px}.account-section{border-top:1px solid #deebf5;margin-top:24px;padding-top:22px}.account-section .fields{margin:20px 0}.account-checks{display:flex;gap:24px;margin:20px 0}.account-checks label{display:flex;gap:8px;align-items:center}.account-checks input{width:16px;height:16px;margin:0}.account-section summary{cursor:pointer;font-size:15px;font-weight:600}.account-section details form{margin-top:20px}.account-user{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:14px 0;border-bottom:1px solid #e8f0f7}.account-user button{padding:7px 12px}.account-section>label input{margin-bottom:22px}.account-section form{margin-top:20px}@media(max-width:600px){.account-checks{flex-direction:column;gap:12px}}
</style>
